  if (typeof event[field] === "string" && (event[field] as string).length > 0) {
    return event[field] as string;
  }
  return evErr(index, "bad " + field);
}

function requireQty(event: Event, index: number, min: number): number | undefined {
  const qty = event.qty;
  if (Number.isInteger(qty) && (qty as number) >= min) return qty as number;
  return evErr(index, "bad qty");
}

// Refill backordered wants that now fit within available stock.
function fulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx.stock, want.item);
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
