interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Event = Record<string, unknown>;
type Handler = (ctx: Context, index: number, event: Event) => string | undefined;

interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const evErr = (index: number, detail: string): string => "event " + index + ": " + detail;
const stockOf = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

// Refill backordered wants that now fit within available stock.
function fulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = stockOf(ctx.stock, want.item);
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

// Return a held order to stock (refilling the queue), or report that it wasn't held.
function releaseReserved(ctx: Context, id: string, status: string): boolean {
  const holding = ctx.reserved[id];
  if (holding === undefined) return false;
  ctx.stock[holding.item] = stockOf(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  fulfillQueue(ctx);
  return true;
}

function handleOrder(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (ctx.orders[id] !== undefined) return evErr(index, "duplicate order");
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) return evErr(index, "bad item");
  const qty = event.qty;
  if (!Number.isInteger(qty) || (qty as number) < 1) return evErr(index, "bad qty");
  const available = stockOf(ctx.stock, item);
  if (available >= (qty as number)) {
    ctx.stock[item] = available - (qty as number);
    ctx.reserved[id] = { item, qty: qty as number };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty: qty as number };
    ctx.orders[id] = "backordered";
  }
}

function handleCancel(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (releaseReserved(ctx, id, "cancelled")) return;
  if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function handleShip(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  const qty = event.qty;
  if (qty !== undefined && (!Number.isInteger(qty) || (qty as number) < 1)) {
    return evErr(index, "bad qty");
  }
  const holding = ctx.reserved[id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (qty === undefined || (qty as number) === holding.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if ((qty as number) < holding.qty) {
    holding.qty = holding.qty - (qty as number);
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
}

function handleRestock(ctx: Context, index: number, event: Event): string | undefined {
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) return evErr(index, "bad item");
  const qty = event.qty;
  if (!Number.isInteger(qty) || (qty as number) < 1) return evErr(index, "bad qty");
  ctx.stock[item] = stockOf(ctx.stock, item) + (qty as number);
  fulfillQueue(ctx);
}

function handleExpire(ctx: Context, index: number, event: Event): string | undefined {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) return evErr(index, "bad id");
  if (!releaseReserved(ctx, id, "expired")) {
    ctx.rejected = ctx.rejected + 1;
  }
}

